      if (!node) return "";
      if (node.tag === "#text") return node.value || "";
      if (node.tag === "annotation" || node.tag === "annotation-xml") return "";
      const kids = (node.children || []).filter((c) => c.tag !== "annotation" && c.tag !== "annotation-xml");
