          title: this.portal.getAssessmentTitle?.() || "Assignment",
          course: this.portal.getCourseName?.() || "",
          week: this.portal.getAssessmentWeek?.() || "",
          isReview: this.portal.isReviewMode(),
          totalQuestions: this.portal.getTotalQuestionCount(),
